import{_ as s,l as o,o as e,c as l,v as t,p as I,x as i,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"MSI / MSI-X 中断","description":"","frontmatter":{"title":"MSI / MSI-X 中断","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/msi-msix.md","filePath":"cs/msi-msix.md","lastUpdated":1789023840000}'),A={name:"cs/msi-msix.md"};function c(S,a,M,E,P,h){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="msi-msi-x-中断" tabindex="-1">MSI / MSI-X 中断 <a class="header-anchor" href="#msi-msi-x-中断" aria-label="Permalink to &quot;MSI / MSI-X 中断&quot;">​</a></h1><div class="epigraph"><p>设备不再拉一根 INTx 线，而是写一个约定的内存地址：这条 Memory Write TLP 被主机构成中断，向量在消息数据里。</p><footer>—— 据 PCI-SIG PCI Express Base Specification；Intel 64 and IA-32 Architectures Software Developer’s Manual 整理</footer></div><p><a href="/cs/pcie-tlp-bar">上一课</a>让设备能发 Memory Write。组成/OS 课的 <a href="/cs/plic-irq">PLIC</a> 是线汇聚模型。缺口是 PCI <strong>消息信号中断</strong>：MSI 与 MSI-X 用写事务代替边沿/电平线，向量可以很多。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 INTx 共享、电平、桥上虚拟线，扩展性差。MSI：配置能力里写 Message Address/Data，设备发一条写。MSI-X：独立表（常在 BAR）每向量各地址/数据，可掩码，向量数远大于 MSI。缺口不是 TLP 头格式重讲，而是：<strong>中断=定向写</strong>，与 DMA 写同类，只是地址落在中断控制器接收窗口（如 x86 的 FEE0_xxxx 或 IOMMU/APIC 区域）。</p><p>RISC-V 平台可用 MSI 接到 IMSIC 或经转换接到 PLIC，细节因平台而异，本课钉 PCI 侧合同。</p><h3 id="msi-不是「更快的轮询」" tabindex="-1">MSI 不是「更快的轮询」 <a class="header-anchor" href="#msi-不是「更快的轮询」" aria-label="Permalink to &quot;MSI 不是「更快的轮询」&quot;">​</a></h3><p>没有消息时 CPU 不因该设备进中断；轮询是软件读门铃。把 MSI-X 理解成硬件自动 poll BAR，中断亲和与节能模型全错。过多向量浪费表项；过少则共享处理函数。</p><p><span class="marginnote">PCI-SIG 定义 MSI/MSI-X 能力结构。Intel SDM 描述本地 APIC 如何接收这些写。下一课 APIC 路由。Linux 驱动写 <code>pci_alloc_irq_vectors</code> 一类，本课不背 API。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>枚举时 OS 分配向量，编程 MSI-X 表，使能。设备事件：写对应表项的地址/数据。主机：APIC 投递到目标 CPU，软件在处理函数里读设备原因寄存器（仍经 BAR）。与 DMA 写序：描述符写完再发 MSI，通常靠 PCIe 的同路径 Posted 序或显式围栏——后课 DMA 再钉。</p>',11)),(e(),I(p,null,{default:i(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVT%5B%22%E8%AE%BE%E5%A4%87%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20WR%5B%22Memory%20Write%20%E5%88%B0%20MSI%20%E5%9C%B0%E5%9D%80%22%5D%0A%20%20WR%20--%3E%20APIC%5B%22%E4%B8%BB%E6%9C%BA%E4%B8%AD%E6%96%AD%E6%8E%A7%E5%88%B6%E5%99%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20APIC%20--%3E%20CPU%5B%22%E7%9B%AE%E6%A0%87%20CPU%20%E5%90%91%E9%87%8F%22%5D%0A%20%20CPU%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AAPIC%20%E5%A6%82%E4%BD%95%E9%80%89%E6%A0%B8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>错误消息（AER）也走 Message TLP，不是 MSI 表，点名区分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课 APIC/IOAPIC/x2APIC 决定向量落到哪颗核，与 <a href="/cs/irq-affinity">irq affinity</a> 软件策略衔接。本课只把 PCI 设备从「拉线」换成「写消息」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 IOMMU 中断重映射表的全部字段，不把虚拟 MSI 注入写成完整 VFIO 课。不讨论中断风暴的全部缓解。</p><p>后课默认：PCIe 设备用 MSI/MSI-X 写消息投递中断；向量在表里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>INTx 共享线被 MSI 写事务替代。</li><li>MSI-X 每向量独立地址/数据，表在 BAR。</li><li>投递窗口由主机中断控制器定义。</li><li>出处：PCI-SIG PCIe Base Spec；Intel SDM。</li></ul>',8))])}const _=s(A,[["render",c]]);export{C as __pageData,_ as default};
